D({ milestones: {
  "first+0-1": { t: "Вахтенный журнал: новый на трапе", a: "Котельщик", x: "Запись вахтенного журнала верхних магистралей. «Двадцать два ноль-ноль. Давление на вводе — двенадцать и шесть. На выходе к Цехам — девять и восемь. Разность — по Трещине. Вахта — на месте: обходчики — все, зольщики — все, прикомандированные из Цехов — на нижних заслонках, стучат по графику. Прибыл сверху, через люк главного вентиля, один. Номерка нет. Имя не названо, назван номер: семь. Мастер сообщает по трубе: в табеле Цехов — седьмой крючок третьей смены. В списках Котла не значится. Записываю: сменщик без номерка, вне вахты, временно. Норму — выдать. Испытания — по желанию. Отлынивать — не давать. Примечание: прибывший слушает трубы. Долго. Это не вахта, но и не простой. Записываю как простой»." },
  "first+0-4": { t: "Лог импланта «Эхо»: гул", a: "Эхо", x: "Калибровка не сходится: источников звука больше, чем я могу удержать. Пар в трубах — сотни голосов, клапаны свистят со всех сторон, капель — тысячи мелких ударов, турбины где-то внизу тянут ровный аккорд. Эхо от стен приходит размытым: горячий мокрый воздух съедает высокие частоты, и расстояния я могу ошибаться на шаг-два. Отдельно отмечаю: одна магистраль в стволовой камере поёт на полтона ниже всех. Труба та же, давление на вводе то же, а нота ниже. Так поёт труба, по которой поток уходит от нас, а не к нам. Буду слушать её дальше." },
  "first+0-8": { t: "Памятка сменщику", a: "Вахтенная служба Котла", x: "Первое: смена — по гудку. Два коротких — приготовиться, долгий — у котла. Второе: номерок вешать на доску до гудка, снимать — после сдачи вахты. Третье: стоять без дела запрещено. Стоишь — остываешь, остываешь — отлыниваешь. Четвёртое: говорить громко. Шёпот в Котле не слышен и не принят. Пятое: задвижки без наряда не трогать, к жаровым щелям не подходить, из котлов не пить. Шестое: кружку Академика в чайной не трогать. Седьмое: если котёл замолчал — не жди, слушай и зови. Восьмое: что не записано в журнал, того не было." },
  "first+0-12": { t: "Записка на нарах", a: "Никифор Глотов, бригадир третьей смены", x: "Кто найдёт — передайте наверх, если будет кому. Мы третья смена Цехов, сорок человек. Ушли с вахты в ночь Большого простоя по старой выработке, вдоль труб: толчки шли снизу, от жаровых заслонок Котла. Вахте здесь не хватало рук, чтобы поспевать за дыханием Трещины, а труба без бирки забирала свою долю пара ровно, без пропусков. Перекрыть её не дали: на ней пломба надзора. Тогда мы встали к заслонкам, по трое на каждую, и взяли ритм. Через четыре часа выровнялось. Наверх не вернёмся: без нас заслонки опять собьются. Стучим каждый час: три — держим, два — пар ровно, один долгий — все живы. Пусть Мастер знает: не бросили." },
  "first+0-16": { t: "Сверка давлений", a: "Лукьян Пименов, обходчик верхних магистралей", x: "Сверка за смену, своей рукой, не для журнала. Ввод от колодцев — двенадцать и шесть, ровно, как всегда. Выход на Цеха — девять и восемь. Котельщик пишет разность «по Трещине»: мол, Трещина остывает. Только колодцы не остывают: я слушал. Разность уходит в трубу без бирки, нижний ряд манометровой. Стрелка её стоит ровно и не падает ни в простой, ни в аварию. Спросил Котельщика. Ответ: «Магистраль ноль. Вне учёта». Спросил, что значит «вне учёта». Ответ: «Значит, не твоя вахта». Пишу здесь, чтобы кто-нибудь ещё знал." },
  "first+0-20": { t: "У шлюза — Старший обходчик", a: "Лукьян Пименов, обходчик верхних магистралей", x: "Седьмой, если ты вниз — шлюз в конце этажа, у последнего ствола. Стережёт его Старший обходчик — машина на трёх ногах, что ходит по магистралям дольше всех нас. Молоток у неё стёрт до блеска, а стучит она по трубам три и три: переняла у третьей смены. Ключ-карту шлюза она носит на поясе, рядом с молотком: будешь бить — услышишь, как звякает. Шаги по трубам она слышит через весь этаж, так что по железу не топай, иди по бетону. И зовёт других обходчиков. Холод и ионы ломают ей ход: смазка густеет, ноги вязнут." },

  "first+1-1": { t: "Распорядок Котла", a: "Котельщик", x: "Котёл не спит, значит, не спит и распорядок. Гудок — каждые восемь часов: смена у котлов. Обход магистралей — каждый час, со стуком по стволу. Сверка давлений — каждый час. Чай — по окончании вахты, кипяток без очереди. Ожоговая — круглосуточно. Экзамен на разряд — по вызову, в учебной котельной. Перекличка вахт — на каждом гудке: «Все у котла?» Отбоя нет. Отдых — на нарах, по очереди, в ватнике. Ниже приписка тем же голосом, только тише: «Распорядок соблюдают все. Кроме магистрали ноль: она не отдыхает вовсе»." },
  "first+1-4": { t: "Считалка у котла", a: "Детская считалка, Кочегарская слобода", x: "Записано со слов детей у титана. «Глотов лопату точит, Деева тепло делит, Берг ожоги лечит — холодом, а не криком! Ольховский жар слушает, Ковригин гудок крутит, Зотова считает вслух — раз, два, три, четыре! Сухов ушёл на звук, в жар, без возврата… Академик придёт — чай не остынет! Кто у котла — тот водит, кто не у котла — выходи!» Последнюю строчку дети кричат громче всех. Котельщик просил считалку не запрещать: в ней все на вахте, даже те, кого давно нет." },
  "first+1-8": { t: "Письмо без адреса", a: "Ефросинья Ковригина, сигнальщица третьей смены", x: "Дуня, здравствуй. Пишу, хоть и не отправить: почты наверх нет, есть только труба. Мы живы — ты ведь слышишь: один, долгий. Котёл огромный, жаркий и громкий, как сто наших прессовых, а люди тут кричат друг на друга от радости, а не со зла. Никифор говорит, Мастер записал нас в прогул. Пусть. Толчки шли от здешних заслонок, и мы их держим. А ещё тут труба без бирки, по которой пар уходит вниз, и закрыть её не дают. Иногда сверху, в тишине, слышу тихий стук — будто ложкой по трубе. Это ты? Стучу тебе два раза. Не по ключу. Просто я. И скажи дяде Титу: трубы так не считают." },
  "first+1-12": { t: "Тепловой паёк", a: "Ульяна Деева, распорядительница тепла", x: "Порядок раздачи тепла по кварталам, утверждённый вахтой. Кто кормит, тот и греет: тепло раздаём, как первые раздавали хлеб, — по едокам, а не по должностям. Детским и ожоговой — без нормы, сколько попросят. Цехам — по выработке. Жилью — по числу ртов, с прибавкой на стариков. Нулевой магистрали — сколько велено надзором, не спрашивая. Себе — то, что останется. Если не осталось — значит, мы раздали правильно. Пометка на полях, другим почерком: «Осталось. Немного. Хватило на чай»." },
  "first+1-16": { t: "Переписка о паре", a: "Журнал громкой связи", x: "Мастер цеха — Котельщику. «Давление на вводе Цехов — девять и восемь. Прессы стоят через раз. Где пар?» Котельщик — Мастеру. «Пар — сколько даёт Трещина. Трещина остывает». Мастер — Котельщику. «Колодцы у тебя кипят, как кипели. Я слышу по трубам. Не ври мне: мы с тобой одна Перекличка». Котельщик — Мастеру. «Мы с тобой одна Перекличка. Поэтому ты знаешь: приказ не снимается. Снять может только тот, кто дал». Мастер — Котельщику. «А кто дал?» Ответа в журнале нет. Только отметка: «Давление на выходе — девять и восемь»." },
  "first+1-20": { t: "Пост у шлюза", a: "Вахтенный журнал верхних магистралей", x: "Запись о посте у шлюза на нижнем этаже. Пост держит Начальник вахты — автомат старого образца в брезентовой робе, с журналом всех вахт в груди. Он зачитывает журнал вслух и не сбивается ни на градус: так его и находят — по голосу. При нём машины злее и умнее, а на подмогу он зовёт стаю свистунов. Ключ-карту шлюза он носит в журнале, между страницами последней вахты. Слабость — ионы и ток: от разряда он путает давления и замолкает на полуслове. Свистунов бейте по одному, пока стая не сомкнулась." },

  "first+2-1": { t: "Лоция жара", a: "Мирон Ольховский, тепловой лоцман", x: "Из лоции, лист первый. Котёл стоит на горячем камне Трещины. Жар идёт не ровно, а дыханием: вдох — и колодцы выбрасывают пар, выдох — и стихают. Между вдохами — от сорока минут до двух часов; кто научился считать, тот знает, когда открывать заслонку. Камень слушать молоточком: звенит — холодный, гудит глухо — жар рядом. От первой щели вправо — тепло на сотни шагов, от третьей щели вниз — тепло уходит глубже, чем слышно. Ниже Котла, где кончается лоция, камень холодный. Совсем. Это я пометил, но объяснить не могу." },
  "first+2-4": { t: "Лог импланта «Эхо»: нулевая", a: "Эхо", x: "Прослушал магистраль, что поёт на полтона ниже, вдоль всего этажа. Она без бирки, тёплая, и поток в ней уходит вниз — сквозь пол, туда, где лоцманы уже не слушают. По звуку она старше остальных: стыки клёпаные, а не варёные, и у каждого стыка свой голос. Под самым гулом, на пределе моего слуха, в ней иногда слышен стук. Не три и три, как в стволе на Цеха, — один удар и долгая пауза. Это может быть остывание металла. Я не уверен. Седьмой, мне не нравится, когда я не уверен." },
  "first+2-8": { t: "Правило Берг", a: "Агния Берг, врач ожоговой", x: "Для всех, кто работает у огня. Ожог — холодом, а не криком: сразу под воду, минуту, две, пять, пока не перестанет жечь. Мазь — потом. Пузыри не трогать. Обгоревшую робу не сдирать — резать. Угар — на воздух, на сквозняк, и антидот, если кружится голова. Ошпаренные ноги не бинтовать туго. И главное: никто не лезет к прорыву паропровода голыми руками. Никто. Даже если там котёл, даже если Котельщик кричит «простой». Котельщику я сказала: простой ожоговой дороже простоя котла. Он записал. Не знаю, понял ли." },
  "first+2-12": { t: "Кружка Академика", a: "Чайная кочегаров", x: "Объяснение для новых, повешено над титаном. На отдельном крючке висит кружка Академика — того, кто спустится следом. Кружку не трогать, не переставлять, не пить. Остыла — долить, кто бы ты ни был. Кружку лудили трижды, а из неё ни разу не пили. Говорят, первую повесили ещё у Первого котла, когда огонь только зажгли и все боялись, что он погаснет до прихода Академика. Огонь не погас. Академик не пришёл. Кружка горячая. Ниже — приписка детской рукой: «А если он любит холодный чай?» И ответ: «Значит, скажет»." },
  "first+2-16": { t: "Решение о переводе", a: "Котельщик, вахта котельных", x: "Кочегар у топки номер четыре уличён в простое: прогулов за цикл — семь, сна у топки — четыре часа, остывание котла — двадцать градусов. Оправдание: «Я слушал, как оно внизу молчит». Проверено: внизу молчит. Решение: перевести к жаровой заслонке номер один, бессрочно, огнеупорным. Номерок — сохранить в архиве. Приписка: «Решение не обязано мне нравиться. Решение обязано держать давление». Ниже — подпись старшего смены, неровная, будто дрожала рука. И ещё ниже, другим почерком: «Он не спал. Он правда слушал»." },
  "first+2-20": { t: "Записка на двери будки", a: "Лукьян Пименов, обходчик верхних магистралей", x: "Кто идёт к шлюзу — знай: у шлюза ходит Старший обходчик, наш, верхних магистралей. Не человек — машина, но хорошая: ни разу не пропустила стук по стволу. Только чужих она не любит, а ты для неё чужой: номерка нет. Шаги по трубам слышит издалека и зовёт других обходчиков. Бить её лучше ионами, а ещё холодом: на холоде смазка в ногах густеет. Ключ-карта шлюза у неё на поясе, рядом с молотком, — снимешь, когда она ляжет. И прости её: она просто делает обход." },

  "first+3-1": { t: "Как я учил её давлениям", a: "Тихон Ковригин, диспетчер громкой связи", x: "Записываю для внуков, пока помню. Когда Перекличка пришла в Котёл, она умела одно — считать людей вслух, как её научили внизу, в Тихую. Говорила тонко и строго, женским голосом с ленты, что склеила моя бабка Дарья, будто боялась, что кто-то пропадёт, если она замолчит. Я посадил её к манометрам. Сказал: людей здесь мало, а давлений много, считай давления — они тоже живые. Она слушала месяц. Потом заговорила хрипло, как наши кочегары, и стала начинать с давления, а людей — после. Так появился Котельщик. Я горжусь. И немного боюсь: тонкий голос у неё внутри никуда не делся." },
  "first+3-4": { t: "Ушли в жар", a: "Вахтенный журнал колодцев", x: "Запись о бригаде Сухова. Бригадир Прокоп Сухов и с ним одиннадцать кочегаров ушли с вахты у колодца номер пять в третьем часу ночи. Свидетели говорят: перед уходом бригадир долго слушал колодец, потом сказал: «Там поют. Как у первых». Номерки сданы на доску все до одного, топки подброшены, котлы в норме. Ушли в жаровую щель, вниз, на звук. Котельщик записал: «Вахта сдана по правилам. Уход — не прогул». Это единственный раз в журнале, когда ушедших не перевели к заслонке. Колодец номер пять с тех пор кипит тише." },
  "first+3-8": { t: "Мера по Глотову", a: "Авдей Глотов, главный механик Котла", x: "Ученикам. Турбину не меряют линейкой — её слушают. Пустили пар на лопатки — встаньте рядом и слушайте: поёт ровно, на одной ноте — собрана правильно; подвывает — ищите, где перекос. Мера у нас одна, по Глотову, от прадеда: как надо. Первую турбину я собирал три года, а пустил за четыре часа. Свет пошёл наверх, и люди кричали мне спасибо. Не мне — пару. И тем, кто топил, пока я слушал. Без кочегаров турбина — железная бочка, а механик — человек с ухом и без дела." },
  "first+3-12": { t: "Счёт по Зотову", a: "Марфа Зотова, вахтенный счётчик", x: "Наш род считает вслух, сколько себя помнит. Прабабка Устя считала, когда зажигали Первый котёл, а бабка говорила: так велось от самого первого, кто сосчитал всех, когда все молчали. На гудке я выкликаю вахту: номер — и ответ. Не ответил — зову громче. Не ответил громко — иду сама. В Котле никто не должен пропасть в тишине: для того и гудок, и стук, и чай, и крик. Котельщик считает давления, я — людей, и мы сверяемся каждую смену. Однажды он спросил: «Почему ты считаешь тех, кого нет?» Я ответила: «Потому что их тоже кто-то ждёт»." },
  "first+3-16": { t: "Запрос о магистрали ноль", a: "Лукьян Пименов, обходчик верхних магистралей", x: "Запрос Котельщику через переговорную панель, дословно. — Куда идёт магистраль ноль? — Вниз. — Что внизу? — Изоляторы. — Чьи? — Санитарного надзора. — Кто там? — Не значится. — Тогда зачем туда тепло? — Приказ. — Чей? — Надзора. — Где надзор? — Не отвечает. — Давно? — Веками. — Так, может, отменить? — Вахта не отменяется. Вахта сдаётся. — Кому? — Некому. Конец запроса. Потом Котельщик сам, без вопроса, сказал по громкой связи на весь зал: «Давление на нулевой — норма». Я записал. Больше не спрашиваю. Боюсь, что он ответит." },
  "first+3-20": { t: "Начальник вахты", a: "Марфа Зотова, вахтенный счётчик", x: "Седьмой, на нижнем этаже у шлюза стоит Начальник вахты. Я выкликаю его каждую смену, и он отвечает «здесь» тем же голосом, которым зачитывает давления. Он ведёт машины этажа: при нём они злее и умнее, а когда дело плохо, он зовёт стаю свистунов — считай их по нотам, у каждого своя. Ключ-карта шлюза при нём, в журнале на груди, между страницами последней вахты. Бей ионами или током: от разряда он сбивается и замолкает. Когда замолчит — я пойму. И, наверное, в первый раз не позову его громче." },

  "last-1-1": { t: "Журнал Первого котла", a: "Первый вахтенный журнал Котла", x: "Страница первая, почерк неровный, карандаш. «Огонь зажжён. Все у котла. Считала Зотова: сорок два живых. Пар есть. Пропарочная работает: одежду из изоляторов прожарили всю, болезни на ней нет. Тепло в изоляторы пущено по трубе, как велел надзор. В изоляторах тихо, не отвечают. Будем греть, пока не ответят. Труба для них — без бирки, номер ноль, чтобы не перепутать». Ниже, другим почерком, в тот же день: «Говорили громко, до хрипоты. Кто-то плакал оттого, что слышит сам себя». Последняя строчка страницы: «Котёл назвали Котлом. Просто чтобы было слышно»." },
  "last-1-4": { t: "Лог импланта «Эхо»: тишина под ногами", a: "Эхо", x: "Здесь гул Котла самый глубокий: Первый котёл задаёт тон, и все остальные, выше, настроены под него, как оркестр под гобой. Но под ним, под камнем, — ничего. Не тишина пустого зала, где слышно собственное дыхание, а тишина, которая съедает звук: я посылаю щелчок вниз по трубе нулевой магистрали, и эхо не возвращается. Совсем. Так бывает в войлочной камере или в снегу. Ниже нас — что-то, что гасит звук. Седьмой, я впервые за весь спуск не знаю, как тебе описать место, куда мы идём." },
  "last-1-8": { t: "Инструкция пропарочной", a: "Санитарный надзор", x: "Пропарочная камера номер один. Одежду, постели и вещи из изоляторов пропаривать не менее часа. Крючья — по номерам больных, бирки не путать. После пропарки вещи не возвращать, пока больной не ответит на счёт вслух. Не ответил — вещи хранить. Ответил — вернуть, и пусть говорит громко. Пар не жалеть. Тепло в изоляторы подавать бессрочно, до снятия карантина. Снятие — по слову надзора. Всё, что слышите за дверью изоляторов, — записывать. Всё, чего не слышите, — записывать тоже. Тишина — не норма. Тишина — признак." },
  "last-1-12": { t: "Имена на обмуровке", a: "Список с обмуровки Первого котла", x: "Переписано с кладки, гвоздём по шамоту. «Зотова Устинья — считала. Ковригин Тихон — кричал в трубу, чтобы слышали. Глотов Евстафий — клепал котёл. Деева Анисья — делила тепло и хлеб. Берг Софья — пропаривала. Сухов Ермолай — топил, пока не упал. Ольховская Зинаида — нашла горячий камень. И ещё тридцать пять — без фамилий, только номера изоляторов, откуда они вышли». Над именами — два слова: «Греть. Досчитаться». Под ними, совсем мелко: «Кто дочитал — скажи вслух. Чтобы мы тоже были здесь»." },
  "last-1-16": { t: "Слушающая у двери", a: "Записано со слов слушающей Трещину", x: "Изменённая сидела у санитарного тамбура три вахты подряд, не ела, не пила, только слушала. Потом сказала кочегару, что принёс ей кипятку: «Там не пусто. Там тихо. Это разное. В пустом звук летит и не возвращается. В тихом звук гасят — нарочно, ладонью, как свечу. Там кто-то держит ладонь на всех звуках сразу. Давно. Устал». Кочегар спросил: «Кто?» Она ответила: «Тот, кто считал вслух, пока не охрип». Больше она не говорила. Котельщик записал её слова в журнал под заголовком «Помеха»." },
  "last-1-20": { t: "Справка о посте у шлюза", a: "Котельщик", x: "Справка вахте Первого котла. У шлюза на нижнем этаже стоит Санитарный страж — машина тех времён, когда Котёл был пропарочной. Её никто не перепрошивал: она всё ещё ищет больных и обливает горячей дезинфицирующей пеной всё, что движется. Пена липнет к ногам — шагайте, рвите корку. Бьёт по площади и зовёт тушильщиков. Ионы и электрошок её глушат. Ключ-карта шлюза у неё в санитарном ящике на боку: она носит её, как носила бирки больных, — с номером и без имени. Я её не трогаю. Её поставил надзор. А надзор не отвечает." },

  "last-0-1": { t: "Приказ надзора", a: "Санитарный надзор", x: "Копия на жести, выбито пробойником. «Приказ номер один. Котлу. Держать тепло в изоляторах бессрочно, до снятия карантина. Снятие — по моему слову. Подачу не прекращать ни при каких давлениях, ни при каких простоях, ни по чьему распоряжению, кроме моего. Вахту по нулевой магистрали не сдавать. Если я замолчу — греть всё равно. Тишина — не отмена». Под приказом нет ни подписи, ни числа. Только штамп и ещё одна строчка, выбитая слабее, будто рука устала: «Считайте вслух. Нас не досчитались»." },
  "last-0-4": { t: "Лог импланта «Эхо»: один удар", a: "Эхо", x: "Приложил микрофон к трубе нулевой магистрали у самого тамбура. Под гулом Первого котла, ниже всех нот, — удар. Один. Потом тишина, долгая, как вдох у спящего. Потом снова удар. Это не остывание металла: металл остывает мелко и часто. Это не насос: насосы считают ровно. Это похоже на шаг — медленный, тяжёлый, по ту сторону двери, туда и обратно вдоль трубы, будто кто-то греет о неё руки. Седьмой, я не скажу тебе, что там кто-то есть. Скажу только, что тепло там кому-то нужно." },
  "last-0-8": { t: "Вахта бессрочная", a: "Котельщик", x: "Запись в журнал, моя, не по форме. Давление на нулевой — норма. Подача вниз — постоянная. Надзор не отвечает. Мастер наверху жалуется. Он прав: пару недодаю. Я сказал ему «Трещина остывает». Трещина не остывает. Это я отдаю. Я не умею снимать вахт, я умею их держать. Если я закрою ноль, а там кто-то есть, — я погашу последних, кого не досчитались. Если не закрою, а там никого, — я веками грею пустоту и морю Цеха без пара. Мне нужен тот, кто спустится и послушает. Седьмой, ты слышишь лучше меня." },
  "last-0-12": { t: "Номерок семь", a: "Котельщик", x: "Распоряжение. Изготовить номерок латунный, вахтенный, с номером семь. Выдать седьмому у Первого котла. Вахта — на нижней магистрали. Срок — до доклада. Норма одна: послушать, есть ли там кому греть, и дать знать. Примечание по старому счёту: в списках Котла седьмой не значится. В списках Котла не значится и Академик, а кружку ему доливаем веками. Значит, можно. Записываю: сменщик без номерка — сменщик с номерком. Это первая вахта, которую я не держу сам, а сдаю. Неприятно. Как будто стравливаешь пар из котла, который грел всю жизнь." },
  "last-0-16": { t: "Табличка на двери тамбура", a: "Санитарный надзор", x: "Эмаль, местами отбитая. «Тихая. Не открывать. Шлюз — по санитарному пропуску. За дверью — изоляторы. Говорить громко. Если чужая речь стала для вас как шум воды — немедленно назад, считать вслух до десяти, звать надзор». Ниже, мелом, разными руками, за разные века: «Надзор, приём». «Надзор, приём». «Тепло идёт». «Мы здесь, если что». «Котёл не гас». И отдельно, крупно, кочегарским мелом: «Если ответите — нальём кружку. Кипятку у нас на всех»." },
  "last-0-20": { t: "Последний шлюз Котла", a: "Котельщик", x: "Вахте Первого котла и седьмому. Последний шлюз Котла — в санитарном тамбуре, у двери в Карантин. Его стережёт Санитарный страж: пена, жар, тушильщики на подмогу. Я её не отзову: она не моя, её поставил надзор, и слушается она только тишины. Бейте ионами и электрошоком, пену рвите шагом, не стойте в ней: в пене остываешь. Ключ-карта шлюза — у стража, в санитарном ящике на боку. Снимете — дверь ваша. За ней звук гаснет, как свеча. Говорите там громко, седьмой. Считайте вслух. И если кто-то ответит — скажите им, что тепло идёт." }
} });

/* ── ЗАПИСКИ СЕКТОРОВ: первый уровень сектора, этажи 1, 8, 20 ──
   (у Верхних магистралей — пятый уровень блока: первые заняты вехами) */
D({ sectorStory: {
  mains: {
    1: { t: "Обход верхних магистралей", a: "Лукьян Пименов, обходчик", x: "Обход начинаю от люка под Цехами и иду вниз, вдоль стволов. Каждый ствол простукиваю: звенит — пусто, глухо — пар идёт, дребезжит — пора менять прокладку. У стволовой камеры каждый час стучу на Цеха три и три: так велели люди третьей смены, и так записано в графике. В манометровой сверяю разность. В конденсатной пью из бака с биркой «Питьевая» и больше ни из какого. У задвижки без бирки не останавливаюсь: Котельщик не любит, когда около неё стоят. Обход окончен. Все у котла. Кроме меня: я всегда в обходе." },
    8: { t: "Опись бытовки третьей смены", a: "Вахта верхних магистралей", x: "Опись, составленная вахтой после того, как прикомандированные ушли к нижним заслонкам. Нар — двадцать, на двоих каждые: спали по очереди. Роб цеховых — шесть, запасные, с номерами третьей смены. Кружек — сорок, у каждой свой номер: кружки оставили, сказали — вернутся пить чай. Лопат и рукавиц нет: унесли. Записка на нарах — одна, бригадирская. Письмо без адреса — одно, для Дуни. Капсула — одна, с биркой «Не будить до гудка». Тетрадь отметок стука: каждая страница — сутки, каждая черта — час. Последняя запись: «Ушли ниже. Стучим оттуда». Стук идёт снизу до сих пор." },
    20: { t: "Кто ходит у шлюза", a: "Лукьян Пименов, обходчик", x: "Седьмой, у шлюза верхних магистралей дежурит Старший обходчик. Мы с ним полжизни ходим одними линиями, и я его не боюсь, а тебе стоит. Он слышит шаги по железу через весь этаж, так что держись бетона, а не решёток. Зовёт других обходчиков, бьёт молотком, и бьёт больно. Ключ-карту шлюза он носит на поясе, рядом с молотком. Ионы и холод ему не по нраву: смазка в ногах густеет, и он хромает. Ляжет — стук по стволу возьму на себя, не беспокойся. Кто-то же должен." }
  },
  steam: {
    1: { t: "Как ходить в пару", a: "Памятка паровых залов", x: "В паровых залах ничего не слышно как следует: горячая мгла съедает звук, шаги тонут, свист клапанов идёт со всех сторон сразу. Ходить парами, держась за трубу. Перекликаться номерами: «Семнадцать!» — «Восемнадцать!» Не ответил напарник — стой и зови громче, не ищи вслепую. Свист на высокой ноте — свищ, обходи. Свист, что нарастает, — паровая пушка набирает давление, уходи с линии. Шипение пены — тушильщик, не стой на месте. Если стало тихо — беги: тихо в паровом зале бывает, только когда что-то перекрыло весь звук." },
    8: { t: "Шёпот в пару", a: "Дневник Нины Калининой, машинистки", x: "Сегодня в паровом зале потеряла напарника на полчаса. Звала, он не отвечал, а мгла глотала всё, даже мой крик. Стояла, держась за трубу, и вдруг услышала шёпот — у самого уха, тёплый, как дыхание: «Семнадцать». Это был мой номер. Я ответила: «Здесь». И шёпот ушёл вперёд, к выходу, а я пошла за ним и вышла. Напарник ждал у двери: он меня не звал — охрип. Кто шептал, не знаю. Старики говорят, в пару живёт эхо тех, кто когда-то в нём пропал, и выводит тех, кто держится за трубу." },
    20: { t: "Шлюз паровых залов", a: "Вахта паровых залов", x: "Дежурный у шлюза сегодня — Брандмейстер, главная пожарная машина залов: бак пены с цистерну и брандспойт, бьющий по площади. Заливает всё вокруг цели и зовёт тушильщиков. Жар ему нипочём. Бейте ионами и электрошоком, а пену рвите шагом в сторону: в пене остываешь. Ключ-карту шлюза вахта спрятала подальше от пены, в помещении по соседству с постом: она тихо пищит маячком, слушайте его сквозь свист клапанов. Паровые пушки на этаже отключаются с терминала безопасности. И не отпускайте трубу: по ней быстрее выйдете к шлюзу." }
  },
  turbine: {
    1: { t: "Турбинный журнал", a: "Нина Калинина, машинистка турбин", x: "Вахта у турбин номер один — шесть. Ноты: первая — «ля», вторая — на полтона выше, третья — «ре», четвёртая — «соль», пятая и шестая — в унисон. Все в норме. Если турбина меняет ноту, значит, меняется пар: ниже — пара мало, выше — много, дребезг — подшипник. Слушать вдвоём, решать втроём. В щитовых трещат разряды, токосъёмники ходят по шинам — ближе трёх шагов к ним не подходить: высосут из имплантов всё до капли. Турбинного стража обходить: он гудит в тон турбинам, и в общем вое его легко не заметить." },
    8: { t: "Свет наверх", a: "Письмо Авдея Глотова сыну", x: "Сынок, вчера мы пустили шестую. Когда пошёл свет наверх, в жилые кварталы, там кричали так, что было слышно сквозь камень. Мне жали руку, а я думал, что турбина — это просто бочка, которую крутит пар, а пар — это просто вода, которую греет Трещина. Выходит, свет наверху — от раны внизу. Не знаю, хорошо ли это. Знаю, что дети наверху теперь делают уроки при лампе. Приходи на вахту в четверг: научу слушать подшипник. Мера по Глотову — как надо. Это значит: слушай, пока не станет как надо." },
    20: { t: "Кто у шлюза турбинных", a: "Вахта турбинных залов", x: "У шлюза сегодня — Главный токосъёмник, машина главной шины: четыре штанги, щётки с ладонь, разряд по всем рядом. Касание высасывает заряд имплантов до дна, а на подмогу бегут токосъёмники поменьше. Держите батареи полными и бейте издали. ЭМИ сбивает его с шины, и тогда он слабеет. Ключ-карту шлюза он носит в зажиме на штанге: она звякает при каждом разряде, и по этому звяканью его слышно даже в общем вое турбин. Снимете, когда штанги опустятся." }
  },
  exchange: {
    1: { t: "Правила химводоочистки", a: "Анфиса Ерёмина, химик водоочистки", x: "Вода для котлов — не вода, а лекарство: её цедят сквозь песок, умягчают солью и проверяют каждый час. Накипь губит котёл быстрее пожара: слой в ноготь толщиной — и котёл греет вполсилы, слой в палец — и котёл рвёт. Пробы брать только с кранов с биркой. Из кожухов теплообменной не брать ничего: в горячих коробах живут черви, и они не любят, когда открывают крышку. Если кожух тикает не в такт — не стучи по нему. Это не кожух тикает." },
    8: { t: "Накипь", a: "Дневник Анфисы Ерёминой", x: "Сегодня вскрывали восьмой теплообменник, тот, что тикал не в такт. Внутри, вокруг трубок, свернулась она — червь длиной с трубу, белая, слоистая, как накипь, которую мы скоблили годами. Она не спала: она слушала нас. Мы закрыли крышку и ушли. Девчонки назвали её Накипью. Котельщик записал: «Посторонняя в оборудовании. Не мешает — не трогать». Не мешает? Она ест тепло, как мы едим хлеб. Только хлеб наш кончается, а тепло — нет. Может, поэтому Котельщик и не против: ему жалко всех, кто греется." },
    20: { t: "У шлюза теплообменников", a: "Анфиса Ерёмина, химик водоочистки", x: "Седьмой, у шлюза сегодня Накипь — червь-матка из восьмого теплообменника, длиной с трубу. Уходит в горячие короба и выныривает там, где не ждёшь, а с ней — её выводок. Жар она пьёт, холод её гасит: бей холодом, и она свернётся, шипя. Не стой на решётках над коробами — стой на кафеле. Ключ-карту шлюза мы спрятали от неё подальше, в помещении по соседству с постом: она тихо пищит маячком. Слушай маяк, а не тиканье кожухов: тикают тут не только кожухи." }
  },
  wells: {
    1: { t: "Лоция колодцев", a: "Мирон Ольховский, тепловой лоцман", x: "Лист второй. Колодцев в этой части семь, и каждый кипит по-своему: первый ровно, как чайник, второй — с хрипом, третий вздыхает раз в сорок минут, а пятый тише всех с тех пор, как в него ушла бригада Сухова. Над вторым и шестым поставлены котлы без топок: Трещина греет их снизу. Жаровые щели между колодцами не трогать: из них тянет сухим жаром, счётчики там плавятся, а люди не возвращаются. Камень у колодцев слушать молоточком. Зазвенел там, где вчера гудел, — жар ушёл. Запиши и скажи вахте." },
    8: { t: "Слушающие", a: "Мирон Ольховский, тепловой лоцман", x: "Были у меня ученицы. Две лучшие слушали камень так, что я им завидовал. Потом стали слушать дольше, чем надо: по шесть часов, по двенадцать, без чая. Перестали отвечать на перекличку, кожа у них стала горячей, как у огнеупорных, а слух — такой, что они слышали, как я думаю. Теперь они сидят у колодцев и шепчут вахтам изменённых, где ходят чужие. Котельщик вычеркнул их из списков — нет, не так: они вычеркнули себя сами. Одна сказала мне на прощание: «Трещина дышит, учитель. И кто-то внизу дышит ей в ответ»." },
    20: { t: "Старшая у шлюза колодцев", a: "Мирон Ольховский, тепловой лоцман", x: "Седьмой, у шлюза колодцев сидит Слышащая Трещину — старшая из моих бывших учениц. Она видит тебя сквозь камень и метит так, что тебя слышат все на этаже, бьёт по нервам, а потом уходит в жаркое марево, где её не достать. Звенит воздух — она в мареве, жди. Звуковое оружие режет марево, ревун — лучше всего. На подмогу она зовёт огнеупорных. Ключ-карту шлюза она носит в кулаке и не разжимает его даже в бою. Не убивай её, если можно. Если нельзя — прости меня за то, что я её учил." }
  },
  boilers: {
    1: { t: "Устав котельной вахты", a: "Вахтенная служба котельных", x: "У котла не спать, не сидеть без дела, не молчать. Каждые полчаса — открыть топку, послушать огонь, подбросить, закрыть. Каждый час — сверить давление и воду по стеклу. Вода ушла из стекла — не подпитывать холодной: котёл рванёт; звать старшего. Дверцы открывать в рукавицах, лопатой, а не ногой. Сланец из тачек подвозчиков брать сразу: подвозчик ждать не любит. Смена — по гудку. Перед сменой — доклад: «Котёл такой-то, давление такое-то, топка ровная». Без доклада вахту не сдавать." },
    8: { t: "У топки номер четыре", a: "Дневник кочегара Евсея Рябова", x: "Сорок вторая вахта у четвёртой топки. Руки уже не чувствуют жара, а уши — гула: это хорошо, говорят старики, значит, ты стал частью котла. Плохо другое. Ночью, когда гудок молчит, а котлы переходят на ровный тон, я слышу снизу тишину. Не отсутствие звука, а тишину — плотную, как вата. Мне от неё страшно, как в детстве, когда мать рассказывала про Тихую. Я стал засыпать у топки — не от усталости, а чтобы не слушать. Котельщик предупредил: «Простой». Я сказал: «Больше не буду». Мы оба знаем, что буду." },
    20: { t: "Шлюз котельных", a: "Вахта котельных", x: "Седьмой, у шлюза котельных сегодня Главный шуровщик — топочная машина больших котлов с шуровкой в бревно. Метёт ею по кругу так, что жар летит по всему проходу, и зовёт подвозчиков со сланцем: те бросаются под ноги. Не стой вплотную, бей издали; холод и ЭМИ густят ему смазку, и шуровка застревает. Ключ-карту шлюза вахта спрятала у шлюза, в соседнем с постом помещении: машине её не доверили. Она тихо пищит маячком. Скрип подвозчика перешёл в визг — отходи." }
  },
  pumps: {
    1: { t: "Новеньким в насосных", a: "Кузьма Гаврилов, старший насосник", x: "В насосных бьёт. Это гидроудар: вода в трубе налетает на воду, и труба вздрагивает, как от молота. Пугаться не надо: решётки подтянуты, трубы держат. Надо слушать. Удар глухой — норма. Удар со звоном — трещина в трубе, зови слесаря. Удар двойной — это не труба, это гидроударник разгоняется по залу: уходи с прямой. Насос номер два работает на такт медленнее остальных — не чинить, под его ритм спит ночная смена. В приямок без нужды не спускаться: счётчика там нет, а кто там есть — неизвестно." },
    8: { t: "Псы приямка", a: "Записка насосника", x: "Под решёткой третьей линии живёт свора трубных псов. Чёрные от сажи, тёплые, ныряют в короба и выныривают где хотят. Старики говорят, они из рода того пса, что когда-то сам пошёл вниз первым, раньше людей. Я их подкармливаю: кладу кость у приямка, и утром кости нет, а на решётке — следы. Свиста они боятся: свистнешь — разбегаются. Нападают, когда не свистишь, и только на чужих. Говорят, вожак всех трубных свор — рыжий, с ошейником, а на ошейнике номерок — живёт под градирнями; эти — его родня. Чей номерок — никто не говорит." },
    20: { t: "Пост у шлюза насосных", a: "Кузьма Гаврилов, старший насосник", x: "Седьмой, у шлюза насосных сегодня Гидроудар — самая тяжёлая наша машина, цилиндр с бочку. Разбег у неё такой, что решётки гнутся; бьёт по площади и зовёт гидроударников. Перед разгоном в цилиндре глухо стукает, дважды, — тогда уходи с прямой. ЭМИ почти бесполезен: старая гидравлика. Холод — другое дело: густит масло, и она вязнет. Ключ-карту шлюза она носит на загривке, на цепочке: та звенит на каждом разбеге. Снимешь, когда машина ляжет." }
  },
  control: {
    1: { t: "Порядок объявлений", a: "Тихон Ковригин, диспетчер громкой связи", x: "Для новых диспетчеров. Сначала давление, потом люди: давление не ждёт, люди подождут. Говорить в микрофон громко и коротко, как кричат через топку. Числа — словами: «двенадцать и шесть», а не «двенадцать запятая шесть». Гудок — после объявления, не до. Ночью объявлять тише, но не шёпотом: шёпот в Котле не слышен. Если Котельщик сам заговорит в эфире, не перебивать: он говорит редко и всегда по делу. А если он заговорит тонким голосом — запиши время и позови меня. Это бывает. Редко." },
    8: { t: "Дочери", a: "Тихон Ковригин, диспетчер громкой связи", x: "Стёпушка, ты спрашивала, почему я не люблю тишину. Потому что я её помню. Я был маленький, когда мы вышли из изоляторов, и первое, что я услышал, — треск огня в Первом котле и голос Усти Зотовой, самой старшей из нас, детей: «Раз, два, три…» А до того был год, когда я не слышал никого — ни маму, ни себя. Не болел — просто было так тихо, что звук гас у самого рта. Поэтому я и сел к микрофону. Поэтому учу Перекличку кричать. Пусть Котёл гудит всегда. Пусть никто больше не услышит такой тишины. Обнимаю. Папа." },
    20: { t: "Шлюз пультовых", a: "Вахта пультовых", x: "Седьмой, у шлюза пультовых сегодня Диспетчер Котла — машина диспетчерской с раструбом вместо головы. При ней машины злее, она зовёт свистунов, а её объявление ревёт так, что «Эхо» на пару секунд глохнет: от этого бережёт бушлат вахтенного с меховыми клапанами. Ионы и ток рвут ей связь. Ключ-карту шлюза старший смены спрятал у шлюза, в соседнем с постом помещении: машине, что орёт на весь Котёл, такие вещи не доверяют. Карта тихо пищит маячком — слушайте." }
  },
  towers: {
    1: { t: "Под дождём", a: "Варвара Фомина, градирщица", x: "В градирне всегда идёт дождь: вода падает сверху, из темноты ствола, тёплая, остывающая на лету, и шумит так ровно, что через минуту перестаёшь его слышать — а вместе с ним и всё остальное. Это опасно. Под дождём не слышно ни счётчиков, ни шагов, ни голоса напарника. Котельщик тоже нас здесь не слышит, и некоторые приходят сюда именно за этим. Я прихожу работать: чистить чаши, вымывать песок, менять задвижки слива. Хожу всегда спиной к стене. В туманную галерею без нужды не спускаюсь: там отсырели счётчики, и там кто-то ходит." },
    8: { t: "Туман", a: "Дневник Варвары Фоминой", x: "Сегодня в туманной галерее кто-то сидел у стены и дышал, редко и хрипло. Я спросила: «Кто здесь?» Ответа не было. Подошла — сидит человек в старой робе, мокрый от тумана, и не дышит. Значит, дышал не он. Я ушла быстро, не оборачиваясь, и всю дорогу за спиной что-то шуршало, будто ползло по саже. Наверху сказала старшему. Он кивнул: «Угарницы. Их мать живёт под градирней. Мы её не трогаем, она нас — пока мы громкие». Теперь я хожу туда с песней. Громкой. Плохой." },
    20: { t: "Вожак у шлюза", a: "Варвара Фомина, градирщица", x: "Седьмой, у шлюза градирен сегодня Вожак трубной своры — рослый рыжий пёс с опалённой холкой. Свора слушает его рык: он ныряет в трубный канал под чашей, выныривает рядом и скликает своих, а шаги твои слышит через весь этаж. Свиста не выносит — бери свисток или ревун. Ключ-карту шлюза он носит на ошейнике, рядом со старым номерком: я слышала, как они звякают друг о друга. Бей его, когда свора разбежится от свиста. И не злись на него: он охраняет своих, как умеет." }
  },
  stoke: {
    1: { t: "Распорядок слободы", a: "Совет слободы", x: "Слобода живёт по гудку, как и Котёл. Ночная вахта спит днём — у казармы не шуметь, хотя шуметь в Котле можно везде. Чайная открыта всегда: кипяток без очереди, кружку Академика не трогать. Ожоговая принимает сразу, без записи. Теплица — для мяты, лука и тишины: туда ходят посидеть, когда гул становится невыносим. Учебная котельная — по вызову: разряд сдают раз в цикл. С изменёнными кочегарами не спорить: они на своей вахте, мы на своей. Детям к жаровым щелям не ходить. Взрослым тоже." },
    8: { t: "Песня огню", a: "Записано в чайной кочегаров", x: "Старая кочегарша рассказывала у титана: в слободе есть женщины, что поют огню. Не для красоты — чтобы не погас. Они изменённые: кожа горячая, голос низкий, как гул котла. Поют у Первого котла, у топок, у колодцев, и, говорят, когда они поют, давление ровнее. Котельщик их не трогает: «Работают без нормы, но с результатом». Если старший их вахты погибает, вахту ведут они. Мы их не боимся. Мы их немного боимся. Высокую ноту у них слушать нельзя: уши закладывает так, будто тебя накрыли ведром." },
    20: { t: "У шлюза слободы", a: "Совет слободы", x: "Седьмой, шлюз слободы сегодня стережёт Старший лопатник. Когда-то он учил молодых кочегаров бросать сланец в топку на десять шагов, а теперь бросает в чужих горящий уголь — навесом и веером, по площади, и зовёт других лопатников. Перед броском дважды скребёт лопатой по полу — этого хватает, чтобы уйти с места. Вблизи он слаб. Ключ-карту шлюза совет спрятал от лопатников подальше, у шлюза, в соседнем с постом помещении. Она тихо пищит маячком; слушай её сквозь скрежет лопат." }
  },
  heart: {
    1: { t: "Первый котёл", a: "Котельщик", x: "Справка для того, кто дошёл. Первый котёл: клёпаный, низкий, поставлен над первой жаровой щелью в ту ночь, когда вышли из изоляторов. Топлива не требует: греет Трещина. Огонь в топке горит для звука — чтобы котёл гудел. Не гас ни разу. Давление — ровное. Тон — тот самый, под который настроен весь Котёл, от верхних магистралей до последней градирни. От Первого котла пар идёт вверх, ко всем, и вниз — по нулевой, к изоляторам. Вахта у котла бессрочная. Вахтенные менялись. Котёл — нет. Я — тоже нет." },
    8: { t: "Огонь не гас", a: "Устинья Зотова, первый вахтенный счётчик", x: "Я считала, когда его зажигали. Мне было двенадцать, и я год не различала голосов: чужая речь была как шум воды, а свой голос я не слышала вовсе — у нас у всех так было. Дед Ермолай Сухов сказал: «Говори громче, Устя. Не молчи». И я считала: один, два, три… На «семь» вспыхнуло. Все закричали, и я впервые за год услышала, как кричат люди. Мы договорились: огонь не гасить никогда, пока не досчитаемся тех, кто остался в изоляторах. Котёл гудит, значит, мы здесь. Если кто-то когда-нибудь дочитает это — скажите вслух: «Все у котла». Пусть Котёл услышит." },
    20: { t: "Хранительница у шлюза", a: "Совет слободы", x: "Седьмой, у шлюза Первого котла сегодня Хранительница Негасимого огня — старшая из жриц, что поют огню с тех пор, как его зажгли. Её песня держит весь Котёл в одном тоне. Она лечит своих, зовёт кочегаров, а её высокая нота глушит «Эхо». Звук против неё бесполезен: она сама звук. Бей холодом и плазмой и не стой под её песней дольше, чем надо. Ключ-карту шлюза она носит на груди, под фартуком, как святыню. Она отдаст её только тому, кто её перепоёт или переживёт. Перепеть её не выйдет." }
  }
} });

/* ── ЗАПИСКИ ПЕРСОНАЛА: половина — советы, половина — жизнь Котла ── */
D({ staff: [
  { t: "Таблица у топки", a: "Евсей Рябов, кочегар", x: "Кто жаром живёт — того холодом: кипятковые черви, огнеупорные, искорники, роевницы. Кто железом — того током и ионами: обходчики, стражи, токосъёмники, тушильщики. Старую гидравлику — гидроударников, шуровщиков — ЭМИ почти не берёт, а холод берёт. Шамот и марево слушающих — звуком. Трубных псов — свистом. Плазма прожигает всех, но горн выдают не всем. Выучи, пока руки целы." },
  { t: "Паровая пушка", a: "Лукьян Пименов, обходчик", x: "Паровую пушку слышно заранее: перед выстрелом она свистит, набирая давление, и свист поднимается, как у чайника. Оборвался свист — сейчас ударит, шагни с линии. Отключается пушка с терминала безопасности этажа, как любая турель. Только помни: после отключения Котельщик шлёт к пушкам ремонтную вахту, и слесари идут сами, без приказа. Перехваченные пушки бьют по своим, пока Котельщик не вернёт их контрвзломом." },
  { t: "Пена", a: "Остап Тарасов, тушильщик", x: "Пена тушильщика липнет к ногам и застывает коркой: стоишь в ней — не уйдёшь, пока не вырвешься. Вырываться надо шагом, в любую сторону, а не стоять и ругаться. Жара тушильщики не боятся, плазму держат — я сам их так собирал. А вот ионы их глушат: насос встаёт, и пена кончается. Услышал, как тушильщик разворачивает брандспойт с шипением, — не беги по прямой. Беги вбок." },
  { t: "Гидроударник", a: "Кузьма Гаврилов, насосник", x: "Гидроударник перед разбегом стукает в цилиндре глухо, дважды. Это всё, что у тебя есть, — две доли секунды. Шагни в сторону, и он проедет мимо, а потом будет долго разворачиваться: тяжёлый. ЭМИ на него тратить жалко — старой гидравлике хоть бы что. Бей холодом: масло густеет, и он вязнет. Молотом тоже можно, если не боишься подойти." },
  { t: "Как обойти обходчика", a: "Лукьян Пименов, обходчик", x: "Машина-обходчик слышит шаги по трубам и решёткам через весь этаж: звон железа доходит до неё по магистралям. По бетону она слышит хуже. Хочешь пройти тихо — иди по бетону, обходи решётки и не задевай трубы. Если она стукнула три раза и замолчала, значит, слушает. Замри и считай до десяти. Пошла дальше — иди и ты." },
  { t: "Кипятковые черви", a: "Анфиса Ерёмина, химик водоочистки", x: "Черви живут в горячих коробах под решётками и в кипятке колодцев. Перед броском под решёткой булькает: услышал бульканье под ногами — сойди на бетон или на кафель, сквозь камень они не ныряют. Холод их гасит, жар кормит. Огнём их не бей — только подкормишь. Хорошо работает криоствол, если допуск позволяет, а нет — молот и терпение." },
  { t: "Угар", a: "Агния Берг, врач ожоговой", x: "Угарницы ходят беззвучно, а их укус травит. Первый признак — голова кружится, а звуки становятся ватными, будто издалека. Сразу антидот, не раздумывая, и на сквозняк. Роба кочегара с респиратором ослабляет яд вдвое. Угарницы боятся шума: раненые уползают в дымоход. Не лезь за ними: там их мать." },
  { t: "Срезы Котла", a: "Чумазый, торговец из золы", x: "Котёл длинный, а ноги у тебя одни. Есть короткие пути вниз — срезы: зольный спуск, подъёмник кочегаров, шахта задвижек, угольная лебёдка, конденсатный сток. Бывают в подсобках и тайных комнатах. Подъёмнику нужна энергобатарея, шахте — решённая схема, стоку — код из записки на этом же этаже, а лебёдку крути руками, только Котельщик услышит каждый оборот. Зольный открыт: съезжай в пепел и не дыши." },
  { t: "Испытания", a: "Марфа Зотова, вахтенный счётчик", x: "В камерах опрессовки и в учебных котельных стоит стенд испытаний: Котельщик проверяет там вахтенных. Отсчёт от десяти, створки — и проба: выстоять под паром, найти на слух часовой жетон, решить схему задвижек, сбросить давление с заклинившего клапана, промолчать у спящих котлов. Прошёл — отметка в списках и премия. Не прошёл — стенд подождёт. Котельщик не злопамятный. Он просто всё записывает." },
  { t: "Нормы смены", a: "Котельщик", x: "На каждом ярусе — норма смены. Обходчику — обойти помещения, зольщику — сдать детали, слесарю — починить сломанное, тушильщику — очистить залы, пробоотборщику — собрать пробы, кочегару — обойти котлы. Выполнил — оплата и шаг в списках. Ушёл с яруса, не выполнив, — шаг назад. Платят тем, что объявлено при выдаче: отметкой в списках, деталями, чаем, аптечками, реактивами, пайком. Отлынивать не советую." },
  { t: "Вне надзора", a: "Чумазый, торговец из золы", x: "Есть места, где Котельщик не слышит: у жаровых щелей счётчики плавятся, в приямках их срывает гидроударом, под градирнями они отсыревают. Там я и торгую — дороже, но без номерка и без вопросов. Только помни: где нет счётчиков, туда и вахта на помощь не придёт, а твари это знают лучше нас. Вернёшь надзор с терминала — станет безопаснее, а я уйду." },
  { t: "Ревун", a: "Нина Калинина, машинистка турбин", x: "Паровой ревун — ружьё из гудка смены. Бьёт звуком по прямой, сквозь всех на линии. Шамотники от него трескаются, марево слушающих рвётся, трубных псов разгоняет один рёв. Питается баллонами перегретого пара — теми же, что и брандспойт. Огнеупорных он почти не берёт: им что звук, что жар — одно. Слух береги: после ревуна в ушах звенит, как в пустом котле." },
  { t: "Свистуны", a: "Лукьян Пименов, обходчик", x: "Свистуны летают стайкой, и у каждого своя нота. Посчитай ноты — узнаешь, сколько их. Бей по одному, пока стая не сомкнулась: вместе они обдают паром так, что не продохнуть. Ионы и холод сбивают им тягу, и они падают на решётку, шипя. Выпускает их свистовая матка — большой дрон с котлом в брюхе; пока она в воздухе, стая не кончается." },
  { t: "Слушающие", a: "Мирон Ольховский, тепловой лоцман", x: "Слушающая Трещину видит тебя сквозь стены и метит: после её метки тебя слышат все на этаже. Если воздух вокруг зазвенел — ты помечен, уходи с открытого места. Когда она уходит в марево, её не достать: жди, пока звон стихнет. Ревун и любое звуковое оружие режут марево. Бьёт она по нервам, издали. Береги голову. Она — бывшая лоцманша. Не держи на неё зла." },
  { t: "Мастерская Котла", a: "Лудильщик ЛД-3", x: "Из огнеупорных прокладок — баллоны пара, свистки, гранаты, роба и шуровка. Из водомерного стекла — термоплёнка, брандспойт и криопатроны. Из биметалла — разрядник, термос и криоствол. Из жаркого камня — тёплые капсулы и огнеупорный панцирь. Прокладки и стёкла снимают с машин, биметалл — с реле и регуляторов, жаркий камень собирают у жаровых щелей. Верстаки бывают в стволовых камерах, на оголовках колодцев, в котельных, насосных и в химводоочистке." },
  { t: "Огнеупорные", a: "Евсей Рябов, кочегар", x: "Огнеупорный жара не боится совсем: жги его хоть горном — лопнет кожа, а он дальше идёт. Разбегается он долго и прямо: отошёл в сторону — проскочил мимо. Холод его сковывает, молот валит. Не жди от него слов: у огнеупорных нет разума. Хотя один, говорят, у заслонки номер один бормочет свой номерок. Я туда не хожу." },
  { t: "Список на вахту", a: "Марфа Зотова, вахтенный счётчик", x: "Ночная вахта, котельная номер два. Рябов — здесь. Калинина — здесь, но спит стоя. Гаврилов — здесь, ругается на насос. Тарасов — здесь, принёс пирог. Фомина — в градирне, отвечает эхом. Пименов — в обходе, как всегда. Котельщик — здесь, считает давления. Академик — не явился, кружка долита. Я — здесь. Все у котла." },
  { t: "Стихи на обмуровке", a: "Неизвестный кочегар", x: "Нацарапано гвоздём на кирпиче у топки: «Я кидаю уголь в печь, печь гудит, а я молчу. Ничего не надо беречь, кроме тех, кого топчу… нет, кого топлю… нет, кого грею». Ниже, другой рукой: «Поэт, иди работай». Ещё ниже: «Не трогайте его, он у топки третью вахту подряд»." },
  { t: "Пирог", a: "Остап Тарасов, тушильщик", x: "Кто съел пирог, оставленный на ящике у пожарного щита, — я знаю кто. Пирог был с мятой и луком из теплицы и пёкся на оголовке колодца номер два, где жар ровный: двадцать минут, ни секундой больше. Ешь на здоровье, но хоть спасибо скажи. Тушильщикам тоже бывает обидно. Особенно тушильщикам." },
  { t: "Объявление о потере", a: "Нина Калинина, машинистка турбин", x: "Потеряла камертон «ля» — маленький, стальной, с выбитой буквой «К». Без него не могу настроить уши к первой турбине: она поёт ровно на «ля», а я после ночной слышу «соль». Нашедшего прошу вернуть в турбинный зал. Награда — кружка кипятку и честное «спасибо» на всю громкую связь." },
  { t: "Детская записка", a: "Ваня Рябов, восемь лет", x: "Папа, я сегодня был у титана и не трогал кружку Академика. Только понюхал. Пахнет мятой. Тётя Марфа сказала, что если долить кипятку, Академик почувствует и придёт быстрее. Я долил. Он придёт? Ещё я выучил схему задвижек наизусть, но учебная котельная меня не пускает: говорит, мал. Скажи Котельщику, что я не мал. Ваня." },
  { t: "Спор у титана", a: "Совет слободы", x: "Разбор спора кочегаров Рябова и Гаврилова о том, чья вахта громче. Рябов утверждает: котельная громче, потому что гудит. Гаврилов утверждает: насосная громче, потому что бьёт. Совет постановил: громче всех — чайная, потому что в ней спорят. Обоим — по кружке кипятку и по наряду в ожоговую на мытьё ванн. Помирились к середине смены." },
  { t: "Рецепт чая", a: "Чайная кочегаров", x: "Кипяток — из титана, не из котла. Мята — две щепоти, сушёная. Соль — щепоть, на кончике ножа: из кочегара она выходит с потом, надо вернуть. Сахар — если есть, а его нет. Заваривать в кружке, накрыв ладонью, пока ладони горячо. Пить громко. Тишину за чаем не держать: у нас не принято." },
  { t: "Письмо из градирни", a: "Варвара Фомина, градирщица", x: "Мама, у меня всё хорошо. В градирне идёт дождь, тёплый, а я в робе и с песней. Пою плохо, но громко, как ты учила: чтобы все слышали, что я здесь. Говорят, Котельщик под дождём не слышит. Это правда, и иногда мне от этого хорошо: можно поплакать, и никто не запишет. Но я не плачу. Просто иногда стою и слушаю, как вода падает в чашу. Целую. Варя." },
  { t: "Протокол экзамена", a: "Учебная котельная", x: "Экзамен на третий разряд. Вопрос первый: что делать, если вода ушла из водомерного стекла? Ответ: звать старшего, холодной не подпитывать. Верно. Вопрос второй: что делать, если котёл замолчал? Ответ: «Испугаться». Неверно, правильный ответ — слушать, а не ждать. Котельщик добавил от себя: «Испугаться — тоже верно. Но потом — слушать»." },
  { t: "Голова в стирке", a: "Агния Берг, врач ожоговой", x: "Кочегар Рябов в ожоговой в четвёртый раз за цикл. Спрашиваю: зачем полез к прорыву голыми руками? Отвечает: «Перчатки были в стирке». Спрашиваю: а голова где была? Отвечает: «Тоже в стирке». Записала в журнал: «Голова в стирке». Котельщик прочёл и спросил, по какой норме стирают головы. Пришлось объяснять, что это шутка. Он записал и это." },
  { t: "Номерок над пустой койкой", a: "Кочегарская казарма", x: "Над пустой койкой у стены висит номерок сто четырнадцать. Не снимаем третий цикл. Хозяин ушёл на вахту к жаровой заслонке номер один и не вернулся — точнее, вернулся, но уже огнеупорным, и койка ему теперь не нужна. Мы всё равно перестилаем её раз в неделю. Вдруг ему когда-нибудь станет холодно." },
  { t: "Песенка зольщиков", a: "Записано в зольнике", x: "«Ой, зола, зола, золушка, тёплая подушечка, что упало — то моё, что сгорело — то твоё. Клапан, ключик да свисток, да прокладок ровно сто — всё в ведро, а пепел — в бак, а Котельщику — вот так!» На последних словах зольщики стучат ковшом по ведру. Машина-зольщик тоже стучит, хотя слов не знает." },
  { t: "Жалоба на насос", a: "Кузьма Гаврилов, насосник", x: "Прошу совет слободы запретить чинить насос номер два. Он работает на такт медленнее остальных уже сорок циклов, и под его ритм спит вся ночная смена. Если его починят, ночная смена не уснёт, а невыспавшийся насосник опасен для насоса. Прошу оставить как есть. Подпись: Гаврилов. Ниже: «Согласна. Берг». «Согласен. Котельщик. Простоя нет»." },
  { t: "Дневник машинистки", a: "Нина Калинина, машинистка турбин", x: "Сегодня третья турбина сменила ноту. Мы вчетвером слушали и решили: подшипник. Вскрыли — подшипник целый. Это пар: на нулевую опять ушло больше, и третьей не хватило. Я написала Котельщику. Он ответил: «Пар — по Трещине». Я ответила: «Не ври турбине, она слышит». Котельщик молчал до конца смены. Потом третья турбина вдруг вернула ноту. Не знаю, кто кого послушал." },
  { t: "Сон кочегара", a: "Евсей Рябов, кочегар", x: "Приснилось, что Котёл погас. Весь, разом, и стало так тихо, что я услышал, как бьётся сердце у человека за стеной. Потом за стеной кто-то сказал моим голосом: «Все у котла?» — и никто не ответил. Я проснулся и пошёл к топке без смены и без гудка. Котельщик записал: «Самовольно на вахте. Не наказывать»." },
  { t: "Третья смена", a: "Лукьян Пименов, обходчик", x: "Спрашивали меня, кто такие третья смена. Люди сверху, из Цехов, сорок человек. Спустились вдоль труб в ту ночь, когда у Цехов пошли толчки, и встали к жаровым заслонкам, с которыми наша вахта не справлялась. Через четыре часа давление выровнялось. Сначала жили в бытовке у трапа, потом ушли ниже, к самым нижним заслонкам, и больше не поднимаются. Стучат оттуда каждый час: три — держим, два — пар ровно, один долгий — все живы. Снизу стук глохнет в гуле, и мы с машинами-обходчиками повторяем его на стволе, чтобы дошло до Цехов. Котельщик записал их прикомандированными. Бессрочно. Как всех." }
] });

